syntax:
std::unique_ptr<T> p1 = std::make_unique<T>(args); // create unique_ptr
std::unique_ptr<T> p2 = std::move(p1); // transfer ownership via move constructor
// p1 becomes null after move

code_example:
std::unique_ptr<std::string> p1 = std::make_unique<std::string>("Hello");
std::unique_ptr<std::string> p2(p1); // Error: no copy constructor for unique_ptr
std::unique_ptr<std::string> p3 = std::move(p1); // Correct: transfer ownership to p3
// p1 is now null, p3 owns the string
